// Distributed lock with Redis SET NX PX
async function withDistributedLock(redis, lockKey, ttlMs, fn) {
  const lockValue = crypto.randomUUID();  // unique to this holder

  // Acquire: SET lockKey lockValue NX PX ttlMs
  const acquired = await redis.set(lockKey, lockValue, {
    nx: true,       // only set if not exists
    px: ttlMs       // auto-expire if holder crashes
  });

  if (!acquired) {
    throw new Error(`Lock '${lockKey}' already held`);
  }

  try {
    return await fn();
  } finally {
    // Release only if we still hold it (atomic Lua script)
    const releaseLua = `
      if redis.call('get', KEYS[1]) == ARGV[1] then
        return redis.call('del', KEYS[1])
      else return 0 end`;
    await redis.eval(releaseLua, 1, lockKey, lockValue);
  }
}

