// Connection pool configuration (pg/node-postgres)
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  database: 'myapp',
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  min: 2,          // always keep 2 connections open
  max: 20,         // never exceed 20 concurrent connections
  idleTimeoutMillis: 30000,   // close idle connections after 30s
  connectionTimeoutMillis: 5000  // fail if no connection available in 5s
});

// Request borrows a connection automatically, returns it on release
async function getUser(userId) {
  const result = await pool.query(
    'SELECT * FROM users WHERE id = $1', [userId]
  );
  return result.rows[0];  // connection returned to pool here
}

