// DataLoader pattern: batch all user lookups within one tick
const DataLoader = require('dataloader');

// batchLoadFn is called once per tick with all accumulated IDs
const userLoader = new DataLoader(async (userIds) => {
  // One DB query for all IDs instead of N queries
  const users = await db.query(
    'SELECT * FROM users WHERE id = ANY($1)', [userIds]
  );
  // Return results in the same order as input IDs
  const userMap = Object.fromEntries(users.map(u => [u.id, u]));
  return userIds.map(id => userMap[id] ?? null);
});

