// Read-through cache: application always reads from cache layer
class ReadThroughCache {
  constructor(redisClient, database, defaultTtlSeconds = 300) {
    this.redis = redisClient;
    this.db = database;
    this.ttl = defaultTtlSeconds;
  }

  async get(key, loaderFn) {
    // Try cache first
    const cached = await this.redis.get(key);
    if (cached) return JSON.parse(cached);

    // Cache miss: fetch from backing store
    const value = await loaderFn();
    if (value !== null) {
      await this.redis.setex(key, this.ttl, JSON.stringify(value));
    }
    return value;
  }
}

