// Cold start mitigation: move initialisation outside the handler
// so it runs ONCE when the instance first starts, not on every request

// BAD: connection created on every invocation (re-creates on cold start too)
exports.handler = async (event) => {
  const db = await createDatabaseConnection(); // slow!
  return db.query(...);
};

// GOOD: connection created once when instance initialises
let db;  // module-level variable — persists across warm invocations
async function getDb() {
  if (!db) db = await createDatabaseConnection();  // only on cold start
  return db;
}

exports.handler = async (event) => {
  const conn = await getDb();  // fast on warm invocations
  return conn.query(...);
};

// Probabilistic early expiration to prevent cache stampede
// (XFetch algorithm)
async function getWithEarlyExpire(redis, key, ttlSeconds, computeFn, beta = 1) {
  const entry = await redis.get(key);

  if (entry) {
    const { value, computedAt, ttl } = JSON.parse(entry);
    const delta = (Date.now() / 1000) - computedAt;  // time to compute last time
    const remainingTtl = ttl - (Date.now() / 1000);

    // Probabilistically recompute before expiry based on remaining TTL
    const shouldRefreshEarly = remainingTtl - (delta * beta * Math.log(Math.random())) < 0;
    if (!shouldRefreshEarly) return value;
  }

  // Recompute
  const start = Date.now() / 1000;
  const newValue = await computeFn();
  const delta = (Date.now() / 1000) - start;
  await redis.setex(key, ttlSeconds, JSON.stringify({
    value: newValue,
    computedAt: start,
    ttl: start + ttlSeconds
  }));
  return newValue;
}

// Write-through cache: writes go to cache AND database synchronously
class WriteThroughCache {
  constructor(redis, database, defaultTtlSeconds = 3600) {
    this.redis = redis;
    this.db = database;
    this.ttl = defaultTtlSeconds;
  }

  async set(key, value) {
    // Write to backing store FIRST (durability)
    await this.db.upsert(key, value);
    // Then update cache (consistency)
    await this.redis.setex(key, this.ttl, JSON.stringify(value));
  }

  async get(key) {
    const cached = await this.redis.get(key);
    if (cached) return JSON.parse(cached);
    // Cache miss: load from DB and warm cache
    const value = await this.db.find(key);
    if (value) await this.redis.setex(key, this.ttl, JSON.stringify(value));
    return value;
  }
}

// Consistent hashing: determine target shard from shard key
class ShardRouter {
  constructor(shards) {
    this.shards = shards;  // [shard0, shard1, shard2, ...]
  }

  // Hash-based routing: userId -> shard index
  getShardForUser(userId) {
    const hash = this.fnv1aHash(userId.toString());
    return this.shards[hash % this.shards.length];
  }

  // FNV-1a hash (simple, fast, good distribution)
  fnv1aHash(str) {
    let hash = 2166136261;
    for (const char of str) {
      hash ^= char.charCodeAt(0);
      hash = (hash * 16777619) >>> 0;  // 32-bit unsigned
    }
    return hash;
  }

  async queryUser(userId) {
    const shard = this.getShardForUser(userId);
    return shard.query('SELECT * FROM users WHERE id = ?', [userId]);
  }
}
